namespace sv_2739414e5cba40d3afce1e85ba45a990.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="form-group avatar-group">
        <label>Avatar</label>
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(editModel.AvatarUrl))
            {
                <img src="@editModel.AvatarUrl" alt="Avatar" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
        </div>
        <span class="avatar-url-display">@editModel.AvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editModel.DisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editModel.Email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="editModel.Bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileEditModel editModel = new();
    private string? successMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            ResetToProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void ResetToProfile()
    {
        if (Profile is null) return;
        editModel = new ProfileEditModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        successMessage = null;
        var updated = new UserProfile(editModel.DisplayName, editModel.Email, editModel.AvatarUrl, editModel.Bio);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        ResetToProfile();
        successMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        StateHasChanged();
    }

    private class ProfileEditModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @if (allChannels.Count > 0)
        {
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        }
        else
        {
            <p class="text-muted">No channels available.</p>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Preferences")
        </button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = new();

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private string? successMessage;
    private bool isSaving;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        allChannels = AllChannels ?? new();
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels ?? new());
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        successMessage = null;
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        StateHasChanged();
    }
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings

<div class="expandable-panel">
    <button class="panel-header" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span class="expand-icon">@(isExpanded ? "▼" : "▶")</span>
    </button>

    @if (isExpanded)
    {
        <div class="panel-body">
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
            @if (successMessage is not null)
            {
                <div class="toast success">@successMessage</div>
            }

            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="currentPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="newPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="confirmPassword" class="form-control" />
            </div>

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isUpdating">
                @(isUpdating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? errorMessage;
    private string? successMessage;
    private bool isUpdating;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePassword()
    {
        errorMessage = null;
        successMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            successMessage = "Password updated successfully!";
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update password: {ex.Message}";
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="security-group">
        <h3>Two-Factor Authentication</h3>
        <div class="twofa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
            <label class="toggle-item">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="Toggle2FA" class="toggle-switch" />
                <span>@(TwoFactorEnabled ? "Disable" : "Enable") Two-Factor Authentication</span>
            </label>
        </div>
        @if (LastPasswordChange.HasValue)
        {
            <p class="text-muted">Last password change: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <div class="security-group">
        <h3>Active Sessions</h3>
        @if (Sessions?.Count > 0)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge current">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
