@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileEditModel editModel = new();
    private string? successMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            ResetToProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void ResetToProfile()
    {
        if (Profile is null) return;
        editModel = new ProfileEditModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        successMessage = null;
        var updated = new UserProfile(editModel.DisplayName, editModel.Email, editModel.AvatarUrl, editModel.Bio);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        ResetToProfile();
        successMessage = null;
    }

