{"path": "/tmp/sv-2739414e5cba40d3afce1e85ba45a990/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @if (allChannels.Count > 0)
        {
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        }
        else
        {
            <p class="text-muted">No channels available.</p>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Preferences")
        </button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = new();

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private string? successMessage;
    private bool isSaving;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        allChannels = AllChannels ?? new();
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels ?? new());
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        successMessage = null;
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        StateHasChanged();
    }
}
"}

