@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="form-group avatar-group">
        <label>Avatar</label>
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(editModel.AvatarUrl))
            {
                <img src="@editModel.AvatarUrl" alt="Avatar" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
        </div>
        <span class="avatar-url-display">@editModel.AvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editModel.DisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editModel.Email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="editModel.Bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileEditModel editModel = new();
    private string? successMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            ResetToProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void ResetToProfile()
    {
        if (Profile is null) return;
        editModel = new ProfileEditModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        successMessage = null;
        var updated = new UserProfile(editModel.DisplayName, editModel.Email, editModel.AvatarUrl, editModel.Bio);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        ResetToProfile();
        successMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        StateHasChanged();
    }

    private class ProfileEditModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

