@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings

<div class="appearance-preview @themeClass @fontClass @(CompactMode ? "compact" : "")">
    <div class="preview-header">
        <h4>Preview</h4>
    </div>
    <div class="preview-content">
        <p class="preview-title">Sample Heading</p>
        <p class="preview-text">This is how your content will look with the selected settings. The theme is <strong>@Theme</strong>, font size is <strong>@FontSize</strong>, and language is <strong>@Language</strong>.</p>
        <div class="preview-card">
            <span class="preview-badge">Notification</span>
            <span>You have 3 new messages</span>
        </div>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "English";
    [Parameter] public bool CompactMode { get; set; }

    private string themeClass => $"preview-theme-{Theme.ToLowerInvariant()}";
    private string fontClass => $"preview-font-{FontSize.ToLowerInvariant()}";
}

@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="selectedLanguage" class="form-control">
            @foreach (var lang in Languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            <span>Compact Mode</span>
        </label>
    </div>

    <AppearancePreview Theme="@selectedTheme" FontSize="@selectedFontSize"
                       Language="@selectedLanguage" CompactMode="@compactMode" />

    <div class="button-group">
        <button class="btn btn-primary" @onclick="Save" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private string? successMessage;
    private bool isSaving;
    private bool hasInitialized;

    private static readonly string[] Languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese" };

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private async Task Save()
    {
        isSaving = true;
        successMessage = null;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Appearance settings saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        StateHasChanged();
    }
}

