@page "/settings"
@namespace sv_2739414e5cba40d3afce1e85ba45a990.Components.Pages.Settings
@using sv_2739414e5cba40d3afce1e85ba45a990.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile" OnSave="SaveProfile" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@notificationPrefs" AllChannels="@allChannels" OnSave="SaveNotifications" />
                    break;
                case "Security":
                    <SecuritySection TwoFactorEnabled="@securitySettings?.TwoFactorEnabled ?? false"
                                     LastPasswordChange="@securitySettings?.LastPasswordChange"
                                     Sessions="@securitySettings?.Sessions"
                                     CurrentSessionId="@currentSessionId"
                                     OnChangePassword="HandleChangePassword"
                                     OnToggle2FA="HandleToggle2FA"
                                     OnRevokeSession="HandleRevokeSession" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@appearanceSettings" OnSave="SaveAppearance" />
                    break;
            }
        }
    </main>
