+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+}
+
+.panel-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    width: 100%;
+    padding: 0.85rem 1.25rem;
+    background: #fafafa;
+    border: none;
+    border-radius: 8px;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+    color: #333;
+}
+
+.panel-header:hover {
+    background: #f0f0f0;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+.expand-icon {
+    font-size: 0.8rem;
+    color: #777;
+}
+
+/* Security */
+.security-group {
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+.twofa-status {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+.status-indicator {
+    font-weight: 600;
+    font-size: 0.9rem;
+}
+
+.status-indicator.enabled {
+    color: #2e7d32;
+}
+
+.status-indicator.disabled {
+    color: #c62828;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.75rem;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #eee;
+}
+
+.sessions-table th {
+    font-weight: 600;
+    color: #555;
+    background: #fafafa;
+}
+
+.badge.current {
+    background: #e3f2fd;
+    color: #1565c0;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    font-weight: 600;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    border-radius: 12px;
+    padding: 1.5rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
+}
+
+.modal-dialog h4 {
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+}
+
+.modal-dialog p {
+    margin-bottom: 1rem;
+    color: #555;
+    font-size: 0.95rem;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    margin: 1.5rem 0;
+    overflow: hidden;
+}
+
+.preview-header {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #e0e0e0;
+    background: #fafafa;
+}
+
+.preview-header h4 {
+    margin: 0;
+    font-size: 0.85rem;
+    color: #777;
+    text-transform: uppercase;
+    letter-spacing: 0.5px;
+}
+
+.preview-content {
+    padding: 1.25rem;
+}
+
+.preview-title {
+    font-weight: 600;
+    font-size: 1.1rem;
+    margin-bottom: 0.5rem;
+}
+
+.preview-text {
+    font-size: 0.9rem;
+    color: #555;
+    margin-bottom: 1rem;
+}
+
+.preview-card {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.6rem 1rem;
+    background: #f5f5f5;
+    border-radius: 6px;
+    font-size: 0.85rem;
+}
+
+.preview-badge {
+    background: #1565c0;
+    color: white;
+    padding: 0.15rem 0.5rem;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    font-weight: 600;
+}
+
+/* Theme variations */
+.preview-theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+}
+
+.preview-theme-dark .preview-header {
+    background: #2d2d2d;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-header h4 {
+    color: #aaa;
+}
+
+.preview-theme-dark .preview-text {
+    color: #bbb;
+}
+
+.preview-theme-dark .preview-card {
+    background: #2d2d2d;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1e1e1e 50%);
+}
+
+.preview-theme-system .preview-content {
+    background: #ffffff;
+}
+
+/* Font size variations */
+.preview-font-small .preview-content { font-size: 0.8rem; }
+.preview-font-medium .preview-content { font-size: 0.95rem; }
+.preview-font-large .preview-content { font-size: 1.1rem; }
+
+/* Compact mode */
+.appearance-preview.compact .preview-content {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.appearance-preview.compact .preview-card {
+    padding: 0.35rem 0.75rem;
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    min-height: 200px;
+    color: #777;
+    font-size: 1.1rem;
+}
+
+/* Utilities */
+.text-muted {
+    color: #777;
+    font-size: 0.85rem;
+}
+

